body.query:
query NodePublishers($key: ID!, $limit: Int!, $offset: Int!) {
  node(key: $key) {
    publisher: organization(limit: $limit, offset: $offset) {
      limit
      offset
      count
      endOfRecords
      results {
        ...PublisherResult
      }
    }
  }
}

fragment PublisherResult on Organization {
  key
  title
  created
  country
  logoUrl
  excerpt
}
